import{_ as p,r as a,o as l,c as d,e as r,a as e,s as t,d as o}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Ошибки и Логирование - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Введение","slug":"введение","link":"#введение","children":[]},{"level":2,"title":"Настройка","slug":"настроика","link":"#настроика","children":[{"level":4,"title":"Детализация ошибок","slug":"детализация-ошибок","link":"#детализация-ошибок","children":[]},{"level":4,"title":"Режимы логгирования","slug":"режимы-логгирования","link":"#режимы-логгирования","children":[]}]},{"level":2,"title":"Типы исключений","slug":"типы-исключении","link":"#типы-исключении","children":[{"level":3,"title":"Application exception","slug":"application-exception","link":"#application-exception","children":[]},{"level":3,"title":"System exception","slug":"system-exception","link":"#system-exception","children":[]},{"level":3,"title":"Validation exception","slug":"validation-exception","link":"#validation-exception","children":[]},{"level":3,"title":"AJAX exception","slug":"ajax-exception","link":"#ajax-exception","children":[]}]},{"level":2,"title":"Обработка исключений","slug":"обработка-исключении","link":"#обработка-исключении","children":[{"level":3,"title":"Где разместить обработчики ошибок?","slug":"где-разместить-обработчики-ошибок","link":"#где-разместить-обработчики-ошибок","children":[]}]},{"level":2,"title":"HTTP exceptions","slug":"http-exceptions","link":"#http-exceptions","children":[{"level":3,"title":"Произвольная страница ошибки","slug":"произвольная-страница-ошибки","link":"#произвольная-страница-ошибки","children":[]}]},{"level":2,"title":"Логгирование","slug":"логгирование","link":"#логгирование","children":[{"level":4,"title":"Контекстная информация","slug":"контекстная-информация","link":"#контекстная-информация","children":[]},{"level":3,"title":"Хелперы","slug":"хелперы","link":"#хелперы","children":[]}]}],"relativePath":"1.x/ru/services/error-log.md","filePath":"1.x/ru/services/error-log.md"}'),s={name:"1.x/ru/services/error-log.md"};function h(g,n,x,u,m,f){const c=a("pre-heading"),i=a("post-heading");return l(),d("div",null,[r(c),n[0]||(n[0]=e("h1",null,"Ошибки и Логирование",-1)),r(i),n[1]||(n[1]=t(`<p><a name="introduction" class="anchor"></a></p><h2 id="введение"><a href="#введение" class="header-anchor">#</a> Введение</h2><p>При первом запуске OctoberCMS обработка ошибок и исключений уже настроена. Вы можете посмотреть логи двумя способами:</p><ol><li>В файле: <code>storage/logs/system.log</code>.</li><li>В административной части сайта: <em>System &gt; Logs &gt; Event Log</em>.</li></ol><p>Запись в журнале создается для определенных <a href="#exception-types">исключений</a>, когда отобразилась страница с ошибкой.</p><p><a name="configuration" class="anchor"></a></p><h2 id="настроика"><a href="#настроика" class="header-anchor">#</a> Настройка</h2><h4 id="детализация-ошибок"><a href="#детализация-ошибок" class="header-anchor">#</a> Детализация ошибок</h4><p>Подробная детализация ошибок вашего приложения, отображаемая в браузере, контролируется параметром <code>debug</code> в файле <code>config/app.php</code>. По умолчанию подробные отчеты об ошибках включены. Это полезно для отладки и устранения различных проблем, которые могут возникнуть при разработке нового приложения. Иначе на странице отобразится только общее сообщение об ошибке.</p><p>Для локальной разработки Вы должны установить для параметра <code>debug</code> значение <code>true</code>. В вашей рабочей среде это значение всегда должно быть <code>false</code>.</p><pre><code>/*
|--------------------------------------------------------------------------
| Application Debug Mode
|--------------------------------------------------------------------------
|
| When your application is in debug mode, detailed error messages with
| stack traces will be shown on every error that occurs within your
| application. If disabled, a simple generic error page is shown.
|
*/

&#39;debug&#39; =&gt; false,
</code></pre><h4 id="режимы-логгирования"><a href="#режимы-логгирования" class="header-anchor">#</a> Режимы логгирования</h4><p>Октябрь поддерживает следующие режимы логгирования: <code>single</code>, <code>daily</code>, <code>syslog</code> и <code>errorlog</code>. Например, если Вы хотите использовать режим <code>daily</code> вместо <code>single</code>, Вы должны изменить параметр <code>log</code> в файле с настройками приложения <code>config/app.php</code>:</p><pre><code>&#39;log&#39; =&gt; &#39;daily&#39;
</code></pre><p><a name="exception-types" class="anchor"></a></p><h2 id="типы-исключении"><a href="#типы-исключении" class="header-anchor">#</a> Типы исключений</h2><p>Октябрь «из коробки» поддерживает несколько видов исключений.</p><p><a name="application-exception" class="anchor"></a></p><h3 id="application-exception"><a href="#application-exception" class="header-anchor">#</a> Application exception</h3><p>Класс <code>October\\Rain\\Exception\\ApplicationException</code> (или просто <code>ApplicationException</code>) - наиболее распространенный тип исключения. Оно используется, когда простое условие не сработало.</p><pre><code>throw new ApplicationException(&#39;You must be logged in to do that!&#39;);
</code></pre><p>Сообщение об ошибке будет упрощено и не будет содержать конфиденциальную информацию, такую как файл php и номер строки.</p><p><a name="system-exception" class="anchor"></a></p><h3 id="system-exception"><a href="#system-exception" class="header-anchor">#</a> System exception</h3><p>Класс <code>October\\Rain\\Exception\\SystemException</code> (или просто <code>SystemException</code>) используется для критических ошибок, которые добавляются в логи.</p><pre><code>throw new SystemException(&#39;Unable to contact the mail server API&#39;);
</code></pre><p>При вызове этого исключения, отображается подробное сообщение об ошибке с номером файла и строки, в которой она произошла.</p><p><a name="validation-exception" class="anchor"></a></p><h3 id="validation-exception"><a href="#validation-exception" class="header-anchor">#</a> Validation exception</h3><p>Класс <code>October\\Rain\\Exception\\ValidationException</code> (или просто <code>ValidationException</code>) используется для ошибок, которые связаны непосредственно с отправкой формы. Сообщение должно содержать массив с полями и сообщениями об ошибках.</p><pre><code>throw new ValidationException([&#39;username&#39; =&gt; &#39;Sorry that username is already taken!&#39;]);
</code></pre><p>Вы также можете передать экземпляр <a href="./../services/validation.html">службы проверки</a>.</p><pre><code>$validation = Validator::make(...);

if ($validation-&gt;fails()) {
    throw new ValidationException($validation);
}
</code></pre><p>При вызове этого исключения <a href="./../ajax/introduction.html">AJAX framework</a> предоставит информацию в удобном для использования формате, и курсор сфокусируется на первом поле, где возникла ошибка.</p><p><a name="ajax-exception" class="anchor"></a></p><h3 id="ajax-exception"><a href="#ajax-exception" class="header-anchor">#</a> AJAX exception</h3><p>Класс <code>October\\Rain\\Exception\\AjaxException</code> (или просто <code>AjaxException</code>) можно рассматривать в качестве «интеллектуальной ошибки». Он вернет 406 ошибку, что позволит передать ему произвольный контент.</p><pre><code>throw new AjaxException([&#39;#flashMessages&#39; =&gt; $this-&gt;renderPartial(...)]);
</code></pre><p><a name="exception-handling" class="anchor"></a></p><h2 id="обработка-исключении"><a href="#обработка-исключении" class="header-anchor">#</a> Обработка исключений</h2><p>Все исключения обрабатываются классом <code>October\\Rain\\Foundation\\Exception\\Handler</code>, который имеет два метода: <code>report</code> и <code>render</code>. Метод <code>report</code> используется для логгирования исключений, а <code>render</code> - для преобразования исключения в ответ, который можно отправить в браузер.</p><p>Вы также можете создавать произвольные обработчики, если это необходимо, при помощи метода <code>App::error</code>. Например, Вы можете создать обработчик, который обрабатывает только экземпляры <code>RuntimeException</code>:</p><pre><code>App::error(function(RuntimeException $exception) {
    // Handle the exception...
});
</code></pre><p>Если обработчик исключений возвращает ответ, этот ответ будет отправлен в браузер, и никакие другие обработчики ошибок не будут вызваны:</p><pre><code>App::error(function(InvalidUserException $exception) {
    return &#39;Sorry! Something is wrong with this account!&#39;;
});
</code></pre><p>Используйте метод <code>App::fatal</code>, чтобы прослушивать фатальные ошибки PHP:</p><pre><code>App::fatal(function($exception) {
    //
});
</code></pre><p>Если у Вас есть несколько обработчиков исключений, то они должны быть определены от наиболее общих до наиболее частных. Так, например, обработчик, который обрабатывает все исключения типа <code>Exception</code>, должен быть определен перед произвольным исключением, таким как <code>SystemException</code>.</p><h3 id="где-разместить-обработчики-ошибок"><a href="#где-разместить-обработчики-ошибок" class="header-anchor">#</a> Где разместить обработчики ошибок?</h3><p>Обработчики ошибок, как и <a href="./../services/events.html">обработчики событий</a>, обычно попадают в категорию «код начальной загрузки». Другими словами, они подготавливают ваше приложение для обработки запросов и должны быть выполнены перед вызовом маршрутизации или контроллера. Поэтому наиболее подходящее для них место - метод <code>boot</code> в <a href="./../plugin/registration.html#registration-methods">файле регистрации плагина</a>. Также Вы можете использовать файл <strong>init.php</strong>, который должен находится в корне папки плагина, для того, чтобы описать логику регистрации обработчиков ошибок.</p><p><a name="http-exceptions" class="anchor"></a></p><h2 id="http-exceptions"><a href="#http-exceptions" class="header-anchor">#</a> HTTP exceptions</h2><p>Такие ошибки могут возникнуть во время обработки запроса от клиента. Это может быть ошибка &quot;Страница не найдена&quot; (http-код 404), &quot;Требуется авторизация&quot; (401) или даже &quot;Ошибка сервера&quot; (500). Для того, чтобы отправить такой ответ, используйте следующее:</p><pre><code>App::abort(404);
</code></pre><p>Опционально, Вы можете установить свой ответ для возврата в браузер:</p><pre><code>App::abort(403, &#39;Unauthorized action.&#39;);
</code></pre><p>Эти исключения могут быть возбуждены на любом этапе обработки запроса.</p><p><a name="custom-error-page" class="anchor"></a></p><h3 id="произвольная-страница-ошибки"><a href="#произвольная-страница-ошибки" class="header-anchor">#</a> Произвольная страница ошибки</h3><p>По умолчанию страница с ошибкой содержит секцию с кодом, номер строки и трассировку стека, где она возникла. Вы можете изменить эту страницу, установив значение параметра <code>debug</code> на <strong>false</strong> в файле с настройками <code>config/app.php</code> и создав страницу со следующим URL: <code>/error</code>.</p><p><a name="logging" class="anchor"></a></p><h2 id="логгирование"><a href="#логгирование" class="header-anchor">#</a> Логгирование</h2><p>По умолчанию October настроен так, чтобы создать один лог-файл в каталоге <code>storage/logs</code>. Вы можете записывать в логи информацию следующим образом:</p><pre><code>$user = User::find(1);
Log::info(&#39;Showing user profile for user: &#39;.$user-&gt;name);
</code></pre>`,64)),n[2]||(n[2]=e("p",null,[o("Существует восемь уровней логгирования, которые определены в "),e("a",{href:"https://datatracker.ietf.org/doc/html/rfc5424",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[o("RFC 5424"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),o(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),o(),e("span",{class:"sr-only"},"(opens new window)")])]),o(": "),e("strong",null,"emergency"),o(", "),e("strong",null,"alert"),o(", "),e("strong",null,"critical"),o(", "),e("strong",null,"error"),o(", "),e("strong",null,"warning"),o(", "),e("strong",null,"notice"),o(", "),e("strong",null,"info"),o(" и "),e("strong",null,"debug"),o(".")],-1)),n[3]||(n[3]=t(`<pre><code>Log::emergency($error);
Log::alert($error);
Log::critical($error);
Log::error($error);
Log::warning($error);
Log::notice($error);
Log::info($error);
Log::debug($error);
</code></pre><h4 id="контекстная-информация"><a href="#контекстная-информация" class="header-anchor">#</a> Контекстная информация</h4><p>Массив с контекстными данными может быть также передан методами журнала. Эти контекстные данные будут отформатированы и отображены в сообщении:</p><pre><code>Log::info(&#39;User failed to login.&#39;, [&#39;id&#39; =&gt; $user-&gt;id]);
</code></pre><p><a name="helpers" class="anchor"></a></p><h3 id="хелперы"><a href="#хелперы" class="header-anchor">#</a> Хелперы</h3><p>Существует несколько глобальных методов, которые упрощают работу с логгированием. Функция <code>trace_log</code> - псевдоним <code>Log::info</code> с поддержкой массивов и исключениями.</p><pre><code>// Write a string value
$val = &#39;Hello world&#39;;
trace_log(&#39;The value is &#39;.$val);

// Dump an array value
$val = [&#39;Some&#39;, &#39;array&#39;, &#39;data&#39;];
trace_log($val);

// Trace an exception
try {
    //
}
catch (Exception $ex) {
    trace_log($ex);
}
</code></pre><p>Функция <code>trace_sql</code> включает ведение журнала при работе с базой данных. При вызове она будет регистрировать каждую команду, отправленную в бд. Эти записи появляются только в файле <code>system.log</code> и не отображаются в журнале в административной части сайта.</p><pre><code>trace_sql();

Db::table(&#39;users&#39;)-&gt;count();

// select count(*) as aggregate from users
</code></pre>`,10))])}const y=p(s,[["render",h]]);export{_ as __pageData,y as default};
